const cfg = $('Parse Config').first().json.cfg;
const srcByName = new Map(cfg.sources.filter(s => s.enabled).map(s => [s.source, s]));
const byKey = new Map($('Limit').all().map(i => [i.json.key, i.json]));

// Dotted paths, so fields.* can reach into nested actor output ("title.text").
const at = (o, path) => path.split('.')
  .reduce((v, k) => (v === null || v === undefined ? undefined : v[k]), o);

// First path present wins — fields.* in sources.json are ordered fallbacks.
const pick = (d, names) => {
  for (const n of names || []) {
    const v = at(d, n);
    if (v !== undefined && v !== null) return v;
  }
  return '';
};

// Same posting on two job boards: compare normalised title + company.
const norm = s => String(s ?? '')
  .replace(/[\u200b\u200c\u200d\ufeff]/g, '')
  .replace(/\u2019/g, "'").replace(/\u00a0/g, ' ')
  .toLowerCase().split(/\s+/).filter(Boolean).join(' ');
const contentKey = (title, company) => `${norm(title)}|${norm(company)}`;

const already = new Map();
for (const row of $('Get Existing Jobs').all()) {
  const r = row.json;
  if (r.title && r.company) already.set(contentKey(r.title, r.company), r.key);
}

const seen = new Set();
const out = [];

for (const item of $('Scrape Jobs').all()) {
  const d = item.json;
  // Read the id with each source's own mapping until one yields a key we asked for.
  let base;
  for (const s of srcByName.values()) {
    const id = String(pick(d, s.fields.id));
    if (id) base = byKey.get(`${s.source}:${id}`);
    if (base) break;
  }
  if (!base) continue;                       // not something we asked for
  seen.add(base.key);

  const F = srcByName.get(base.source).fields;
  const title = pick(d, F.title);
  const company = pick(d, F.company);
  const description = String(pick(d, F.description));
  const closedVal = pick(d, F.closed);
  const closed = closedVal === true || String(closedVal).toLowerCase() === 'closed';

  const ck = contentKey(title, company);
  const dupeOf = already.get(ck);

  let skip = '';
  if (closed) skip = 'closed';
  else if (!description.trim()) skip = 'no description';
  else if (dupeOf && dupeOf !== base.key) skip = `duplicate of ${dupeOf}`;

  if (!skip) already.set(ck, base.key);      // also catches dupes within this run

  out.push({ json: {
    ...base,
    title, company,
    location: pick(d, F.location),
    full_text: description,
    status: skip ? 'skipped' : 'new',
    skip_reason: skip,
  }});
}

// Asked for but never returned — record it so we do not re-scrape nightly.
for (const base of byKey.values()) {
  if (seen.has(base.key)) continue;
  out.push({ json: {
    ...base, title: '', company: '', location: '', full_text: '',
    status: 'skipped', skip_reason: 'not returned by actor',
  }});
}

return out;

