SLOT_BY_FILE = {
  "request.md": "request",
  "profile.en.md": "profile_en",
  "profile.de.md": "profile_de",
}

slots = {"request": "", "profile_en": "", "profile_de": ""}

for item in _items:
  j = item["json"]
  slot = SLOT_BY_FILE.get(j.get("fileName") or "")
  if slot:
    slots[slot] = str(j.get("data") or "").strip()

if not slots["request"]:
  raise ValueError("Missing request.md in /jd-config")
if not slots["profile_en"]:
  raise ValueError("Missing profile.en.md in /jd-config")

profile_de = slots["profile_de"] or "(not provided — use the English profile)"

system = (
  slots["request"] + "\n\n"
  + "=== USER PROFILE (English) ===\n" + slots["profile_en"] + "\n\n"
  + "=== USER PROFILE (German) ===\n" + profile_de + "\n"
)

return [{"json": {"system": system}}]

import re

cfg = _items[0]["json"]["cfg"]
sources = [s for s in cfg.get("sources", []) if s.get("enabled")]
if not sources:
    raise ValueError('sources.json: no enabled sources')

compiled = []
for s in sources:
    where = f"sources[{s.get('source') or '?'}]"
    if not s.get("source"):
        raise ValueError('sources.json: an entry has no "source"')
    if not s.get("idPatterns"):
        raise ValueError(f"sources.json: {where}.idPatterns is empty")
    if not s.get("jobUrlTemplate"):
        raise ValueError(f"sources.json: {where}.jobUrlTemplate is empty")
    if not (s.get("apify") or {}).get("actorId"):
        raise ValueError(f"sources.json: {where}.apify.actorId is empty")
    if not (s.get("apify") or {}).get("inputKey"):
        raise ValueError(f"sources.json: {where}.apify.inputKey is empty")
    compiled.append((s, [re.compile(p, re.I) for p in s["idPatterns"]]))

out = []
emitted = set()

for item in _items:
    m = item["json"]
    body = "\n".join([m.get("html") or "", m.get("text") or "", m.get("snippet") or ""])
    body = re.sub(r"&amp;", "&", body, flags=re.I)
    body = re.sub(r"&#x2f;", "/", body, flags=re.I)
    body = body.replace("&#47;", "/")

    for src, regexes in compiled:
        for rx in regexes:
            for hit in rx.finditer(body):
                job_id = hit.group(1)
                key = f"{src['source']}:{job_id}"
                if key in emitted:
                    continue
                emitted.add(key)
                out.append({"json": {
                    "key": key,
                    "source": src["source"],
                    "external_id": job_id,
                    "url": src["jobUrlTemplate"].replace("{id}", job_id),
                    "fetched_at": m.get("fetched_at"),
                    "actor_id": src["apify"]["actorId"],
                    "input_key": src["apify"]["inputKey"],
                    "actor_input": src["apify"].get("input") or {},
                }})

return out

