const res = $json;

if (res.stop_reason === 'max_tokens') throw new Error('Reply hit max_tokens — JSON truncated.');
if (res.stop_reason === 'refusal') {
  throw new Error(`Model refused: ${res.stop_details?.category ?? 'unknown'}.`);
}

// Thinking blocks come before the answer on this model, so find the text block, don't index it.
const text = (res.content || []).find(c => c.type === 'text')?.text;
if (!text) throw new Error('No text block in the response.');

const analysis = JSON.parse(text);

// The schema can no longer carry minimum/maximum, so the 0-100 range is enforced here.
const clamp = (n) => Math.min(100, Math.max(0, Math.round(Number(n) || 0)));
analysis.fit_score = clamp(analysis.fit_score);
analysis.combined_score = clamp(analysis.combined_score);

const { body, ...job } = $('Build Anthropic Request').item.json;

return { json: {
  ...job,
  analysis,
  status: 'analysed',
  analysed_at: new Date().toISOString(),
  usage: res.usage,
}};

const { body, ...job } = $('Build Anthropic Request').item.json;
return { json: {
  ...job,
  status: 'error',
  skip_reason: String($json.error?.message ?? $json.error ?? 'LLM call failed'),
}};

const c = $('Parse Config').first().json.cfg;
const THRESHOLD = c.digest.scoreThreshold;
const providerOf = new Map(c.sources.map(s => [s.source, s.provider]));

const esc = s => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const items = $input.all().map(i => i.json)
  .filter(j => j.status === 'analysed' && j.analysis)
  .sort((x, y) => y.analysis.fit_score - x.analysis.fit_score
               || y.analysis.combined_score - x.analysis.combined_score);

const count = items.length;
const sourcesSeen = [...new Set(items.map(j => j.source))];
const PROVIDER = sourcesSeen.length === 1 ? (providerOf.get(sourcesSeen[0]) || 'JD') : 'JD';
const generated_at = new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC';

const list = (cls, heading, arr) => (arr && arr.length)
  ? `<div class="section"><h3>${heading}</h3><ul class="${cls}">`
    + arr.map(x => `<li>${esc(x)}</li>`).join('') + '</ul></div>'
  : '';

const cards = items.map(j => {
  const a = j.analysis;
  const sc = a.combined_score >= THRESHOLD ? 'score-high'
           : a.combined_score >= THRESHOLD - 20 ? 'score-mid' : 'score-low';
  return `
  <div class="card ${a.combined_score < THRESHOLD ? 'below' : ''}">
    <h2>${esc(j.title)}</h2>
    <div class="company">${esc(j.company)}${j.location ? ' · ' + esc(j.location) : ''}</div>

    <div class="badges">
      <span class="badge ${sc}">${a.combined_score}% combined</span>
      <span class="badge action">${a.fit_score}% fit</span>
      <span class="badge like-${esc(a.like_verdict)}">would ${esc(a.like_verdict)}</span>
      <span class="badge action">${esc(String(a.language).toUpperCase())}${a.tone ? ' · ' + esc(a.tone) : ''}</span>
      <span class="badge source">${esc(providerOf.get(j.source) || j.source)}</span>
    </div>

    <div class="summary">${esc(a.summary)}</div>
    ${list('pros', 'Pros', a.pros)}
    ${list('cons-hard', 'Hard gaps', a.cons_hard)}
    ${list('cons-soft', 'Soft gaps', a.cons_soft)}

    <div class="section"><h3>Would you like it?</h3>
      <div class="summary">${esc(a.like_rationale)}</div></div>
    ${(a.salary_range || a.salary_ask) ? `
    <div class="section"><h3>Salary</h3>
      <div class="summary">${esc(a.salary_range)}${a.salary_ask ? ' · recommended ask: ' + esc(a.salary_ask) : ''}</div></div>` : ''}
    ${j.url ? `<div class="section"><a href="${esc(j.url)}">View posting →</a></div>` : ''}
  </div>`;
}).join('');

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<style>
  body { font-family: -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
         color: #1a1a1a; background: #f4f5f7; margin: 0; padding: 16px; }
  .wrap { max-width: 720px; margin: 0 auto; }
  h1 { font-size: 18px; margin: 0 0 4px; }
  .meta { color: #6b7280; font-size: 13px; margin-bottom: 16px; }
  .card { background: #fff; border: 1px solid #e5e7eb; border-radius: 10px;
          padding: 16px 18px; margin-bottom: 14px; }
  .card h2 { font-size: 16px; margin: 0 0 2px; }
  .company { color: #374151; font-size: 14px; margin-bottom: 10px; }
  .badges { margin-bottom: 10px; }
  .badge { display: inline-block; font-size: 12px; font-weight: 600; border-radius: 999px;
           padding: 2px 10px; margin-right: 6px; color: #fff; }
  .action { background: #374151; }
  .source { background: #fff; color: #374151; border: 1px solid #d1d5db; }
  .like-like { background: #047857; } .like-neutral { background: #6b7280; }
  .like-dislike { background: #b91c1c; }
  .score-high { background: #047857; } .score-mid { background: #b45309; }
  .score-low { background: #6b7280; }
  .summary { white-space: pre-wrap; font-size: 14px; margin: 8px 0; }
  .section { margin-top: 10px; }
  .section h3 { font-size: 13px; text-transform: uppercase; letter-spacing: .03em;
                color: #6b7280; margin: 0 0 4px; }
  ul { margin: 0; padding-left: 18px; font-size: 14px; }
  .pros li { color: #065f46; } .cons-hard li { color: #991b1b; } .cons-soft li { color: #92400e; }
  a { color: #1d4ed8; }
  .below { opacity: .72; }
</style>
</head>
<body>
<div class="wrap">
  <h1>Job digest — ${count} new job${count === 1 ? '' : 's'}</h1>
  <div class="meta">Generated ${generated_at} · highlighting matches ≥ ${THRESHOLD}%</div>
${cards}
</div>
</body>
</html>`;

return [{ json: { count, html, subject: `${PROVIDER} JD digest — ${count} new job(s)` } }];

const now = new Date().toISOString();

return $('Merge Streams').all().map(i => {
  const j = i.json;
  const analysed = j.status === 'analysed';
  return { json: {
    key: j.key,
    source: j.source,
    external_id: j.external_id,
    url: j.url || '',
    title: j.title || '',
    company: j.company || '',
    location: j.location || '',
    full_text: j.full_text || '',
    status: analysed ? 'notified' : j.status,
    fit_score: j.analysis ? j.analysis.fit_score : 0,
    combined_score: j.analysis ? j.analysis.combined_score : 0,
    analysis_json: j.analysis ? JSON.stringify(j.analysis) : '',
    skip_reason: j.skip_reason || '',
    fetched_at: j.fetched_at || '',
    analysed_at: j.analysed_at || '',
    notified_at: analysed ? now : '',
  }};
});
